entries[55974] = { ["name"] = "Siedendes Blut", ["text"] = "Sofort 15 sek. Abklingzeit\nVerursacht, dass alle Krankheitseffekte auf Zielen innerhalb von 30 Metern schmerzvoll ausbrechen und dabei 17 bis 20 Schaden verursachen (modifiziert durch Angriffskraft). Zwingt alle Ziele dazu, bis Abbruch lang den Todesritter anzugreifen." }
entries[55975] = { ["name"] = "Bösartigkeit", ["text"] = "45 Meter Reichweite\nSofort\nVersetzt eine freundliche Einheit 8 Sek. lang in einen Blutrausch, erhöht ihren verursachten körperlichen Schaden um 40%, lässt sie jedoch pro Sekunde 1% ihrer maximalen Gesundheit verlieren." }
entries[55976] = { ["name"] = "Zauberabwehr", ["text"] = "Wirken in 1 sek.\nGreift in der Nähe befindliche Feinde mit einem Wirbel von Stahl an, der 6 Sek. lang anhält und alle 2 Sek. Waffenschaden verursacht. Verleiht dem Zaubernden zeitweilige Magie-Immunität." }
entries[55977] = { ["name"] = "Wirbelwind", ["text"] = "Sofort\nInflicts Physical damage to all enemies within 5 yards." }
entries[55978] = { ["name"] = "Herzstoß", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nEin brutaler Angriff, der den Gegner sofort schlägt und 150% Waffenschaden plus für jede auf das Ziel wirkende Krankheit zusätzlich 923 Schaden verursacht. Ziele dieses Angriffs können 10 Sek. lang nicht von Tempoeffekten profitieren." }
entries[55980] = { ["name"] = "Mammuttrampeln", ["text"] = "Wirken in 0.25 sek. 4 sek. Abklingzeit\nVerursacht bei Feinden innerhalb von 10 Metern 155 Schaden." }
entries[55981] = { ["name"] = "Mammuttrompeten", ["text"] = "40 Meter Reichweite\nSofort 10 sek. Abklingzeit\nVerspottet das Ziel, damit es Euch angreift, hat aber keinerlei Effekt, wenn das Ziel Euch bereits angreift." }
