entries[56030] = { ["name"] = "Frostgewirkte Gamaschen", ["text"] = "Wirken in 2 sek.\nReagenzien:\nFroststoffballen (5), Eterniumfaden\nOptionale Reagenzien:\n[] (#47)\nBerufsausbilder:\nSchneiderei von Nordend (5)\nKosten:\n15\n\nFrostgewirkte Gamaschen\nWird beim Anlegen gebunden\nBeine Stoff\n3 Rüstung\n+5 Intelligenz\n+4 Ausdauer\n+ 5 Vielseitigkeit\nHaltbarkeit 85 / 85\n28\n\nFrostgewirkte Macht (0/8)\nFrostgewirkter Gürtel\nFrostgewirkte Stiefel\nFrostgewirkte Handschuhe\nFrostgewirkte Gugel\nFrostgewirkte Gamaschen\nFrostgewirkte Robe\nFrostgewirkte Schultern\nFrostgewirkte Gelenkbänder" }
