entries[56032] = { ["name"] = "Giftschauer", ["text"] = "Sofort\nSchießt Gift auf Feinde vor den Zaubernden, verursacht 616 Naturschaden." }
entries[56033] = { ["name"] = "Disziplinarrute", ["text"] = "Nahkampfreichweite\nSofort\nEinen erschöpften Vrykul schlagen, damit er zurück an die Arbeit geht (vielleicht greift er Euch auch an, wenn Ihr Pech habt)." }
entries[56034] = { ["name"] = "Zauberfaden des Meisters", ["text"] = "Wirken in 4 sek.\nBenötigt Hosen\nReagenzien:\nEterniumfaden\nDieses Rezept verbessert sich eigenständig, sobald Ihr 500 Fertigkeitspunkte in Schneiderei erlangt.\n\nBestickt Eure Hose dauerhaft mit einem Zauberfaden des Meisters, wodurch die Zaubermacht um 10 und die Ausdauer um 6 erhöht wird.\n\nNur die Hose des Schneiders kann bestickt werden und sie wird dadurch seelengebunden." }
entries[56035] = { ["name"] = "Geschwächte Seele", ["text"] = "(Procchance: 50%, 8s Abklingzeit)" }
entries[56036] = { ["name"] = "Rune der Zerstörung", ["text"] = "5% von Grundmana 30 Meter Reichweite\nSofort\nMarkiert einen Feind 5 Sek. lang mit einer feurigen Rune, welche nach Ablauf von 5 Sek. Schaden verursacht." }
entries[56037] = { ["name"] = "Rune der Zerstörung", ["text"] = "30 Meter Reichweite\nSofort\nMarkiert einen Feind 5 Sek. lang mit einer feurigen Rune, welche nach Ablauf von 5 Sek. 12 Feuerschaden verursacht." }
entries[56038] = { ["name"] = "Seuchenblitz", ["text"] = "35 Meter Reichweite\nWirken in 2.5 sek.\nEin Seuchengeschoss direkt aus Varguls verkümmertem Herz. Genutzt, um Feinde zu foltern. Verursacht 5 Schattenschaden." }
entries[56039] = { ["name"] = "Geweihter Zauberfaden", ["text"] = "Wirken in 4 sek.\nBenötigt Hosen\nReagenzien:\nEterniumfaden\nDieses Rezept verbessert sich eigenständig, sobald Ihr 500 Fertigkeitspunkte in Schneiderei erlangt.\n\nBestickt Eure Hose dauerhaft mit einem geweihten Zauberfaden, wodurch die Zaubermacht um 10 und die Willenskraft um 4 erhöht wird.\n\nNur die Hose des Schneiders kann bestickt werden und sie wird dadurch seelengebunden." }
